-- YG-552 randevu teyidi; Cilt I §9 gösterge hedefleri ve ramak kala kaydı; YG-762 nakit tahmini genel gider planı.
ALTER TABLE randevu_bildirimi ADD COLUMN teyit_belirteci text UNIQUE, ADD COLUMN teyit text CHECK (teyit IN ('Katılacağım', 'Uygun Değil')), ADD COLUMN teyit_notu text, ADD COLUMN kaptan_ad text, ADD COLUMN kaptan_telefon text, ADD COLUMN teyit_zamani timestamptz, ADD COLUMN teyit_adresi text;
CREATE TABLE gosterge_hedefi (kod text PRIMARY KEY, hedef numeric, uyari_esigi numeric, kritik_esik numeric, gerekce text NOT NULL, guncelleyen_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik), zaman timestamptz NOT NULL DEFAULT now());
CREATE TABLE ramak_kala (kimlik bigserial PRIMARY KEY, faaliyet text NOT NULL, aciklama text NOT NULL, dosya_ref uuid REFERENCES dosya (kimlik), bildiren_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik), zaman timestamptz NOT NULL DEFAULT now());
CREATE TABLE nakit_gider_plani (kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), kalem text NOT NULL, tutar_eur numeric(14,2) NOT NULL CHECK (tutar_eur > 0), tekrar text NOT NULL CHECK (tekrar IN ('Aylık', 'Tek Sefer')), ayin_gunu integer CHECK (ayin_gunu BETWEEN 1 AND 28), tarih date, baslangic date, bitis date, aktif boolean NOT NULL DEFAULT true, giren_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik), zaman timestamptz NOT NULL DEFAULT now(), CHECK ((tekrar = 'Aylık' AND ayin_gunu IS NOT NULL) OR (tekrar = 'Tek Sefer' AND tarih IS NOT NULL)));
GRANT SELECT, INSERT, UPDATE ON gosterge_hedefi, nakit_gider_plani TO yatonet_uygulama; GRANT SELECT, INSERT ON ramak_kala TO yatonet_uygulama; GRANT USAGE ON SEQUENCE ramak_kala_kimlik_seq TO yatonet_uygulama;
ALTER TABLE kurumsal_rapor ADD COLUMN pdf_surum_ref uuid REFERENCES belge_surum (kimlik);
